116	
117	        return bodyFormData
118	                // Disregard keys that are null
119	                .stream()
120	                .filter(property -> property.getKey() != null)
121	                .map(property -> {
122	                    String key = property.getKey();
123	                    String value = (String) property.getValue();
124	
125	                    if (encodeParamsToggle == true) {
126	                        try {
127	                            value = URLEncoder.encode(value, StandardCharsets.UTF_8.toString());
128	                        } catch (UnsupportedEncodingException e) {
129	                            throw new UnsupportedOperationException(e);
130	                        }
131	                    }
132	
133	                    return key + "=" + value;
134	                })
135	                .collect(Collectors.joining("&"));
136	    }
