32	/**
33	 * This filter captures the request that was sent out via WebClient so that the execution response can
34	 * accurately represent the actual request used
35	 */
36	@Getter
37	public class RequestCaptureFilter implements ExchangeFilterFunction {
38	
39	    private ClientRequest request;
40	    private final ObjectMapper objectMapper;
41	    private final BodyReceiver bodyReceiver = new BodyReceiver();
42	
43	    public RequestCaptureFilter(ObjectMapper objectMapper) {
44	        this.objectMapper = objectMapper;
45	    }
46	
47	    @Override
48	    @NonNull public Mono<ClientResponse> filter(@NonNull ClientRequest request, ExchangeFunction next) {
49	        this.request = request;
50	        return next.exchange(request);
51	    }
