168	    static class OneValueConsumption<T> implements Subscriber<T> {
169	
170	        private final Consumer<T> consumer;
171	        private int remainedAccepts;
172	
173	        public OneValueConsumption(Consumer<T> consumer) {
174	            this.consumer = Objects.requireNonNull(consumer);
175	            this.remainedAccepts = 1;
176	        }
